final items = ['a', 'b', 'c'];

ListView.builder(
  itemCount: items.length,
  itemBuilder: (context, index) {
    return ListTile(title: Text('Item ${items[index]}'));
  },
)

validator: (value) {
  if (value == null || value.isEmpty) return 'Veuillez entrer votre email';
  if (!value.contains('@')) return 'Email invalide';
  return null;
},
